package com.example.finance;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.YearMonth;

/**
 * Answers "what if I spent less in category X and put that money toward
 * savings goal Y instead?" — a pure preview, computed from a hypothetical
 * reduction in the category's actual spend for the month. Nothing here
 * writes a transaction, contribution, or category change.
 */
public class ReallocationService {

    private final BudgetService budgetService;
    private final SavingsGoalService savingsGoalService;
    private final SavingsGoalRepository savingsGoalRepository;

    public ReallocationService(BudgetService budgetService, SavingsGoalService savingsGoalService,
                                SavingsGoalRepository savingsGoalRepository) {
        this.budgetService = budgetService;
        this.savingsGoalService = savingsGoalService;
        this.savingsGoalRepository = savingsGoalRepository;
    }

    public ReallocationProjection project(String categoryName, BigDecimal reductionAmount, String goalName,
                                           YearMonth month) {
        if (reductionAmount == null || reductionAmount.signum() <= 0) {
            throw new IllegalArgumentException("Reduction amount must be positive.");
        }

        BudgetService.CategoryTotal categoryTotal = budgetService.categoryTotals(month).stream()
                .filter(t -> t.getCategory().getName().equals(categoryName))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No such category: \"" + categoryName + "\"."));

        SavingsGoal goal = savingsGoalRepository.findAll().stream()
                .filter(g -> g.getName().equals(goalName))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No such savings goal: \"" + goalName + "\"."));

        BigDecimal newRemainingInCategory = categoryTotal.getRemaining().add(reductionAmount);
        BigDecimal newSavedAmount = savingsGoalService.totalSaved(goalName).add(reductionAmount);
        double newProgressPercent = goal.getTargetAmount().signum() <= 0
                ? 0.0
                : newSavedAmount.divide(goal.getTargetAmount(), 4, RoundingMode.HALF_UP).doubleValue();

        return new ReallocationProjection(categoryTotal.getCategory(), reductionAmount, newRemainingInCategory,
                goal, newSavedAmount, newProgressPercent);
    }

    public static class ReallocationProjection {
        private final Category category;
        private final BigDecimal reductionAmount;
        private final BigDecimal newRemainingInCategory;
        private final SavingsGoal goal;
        private final BigDecimal newSavedAmount;
        private final double newProgressPercent;

        public ReallocationProjection(Category category, BigDecimal reductionAmount, BigDecimal newRemainingInCategory,
                                       SavingsGoal goal, BigDecimal newSavedAmount, double newProgressPercent) {
            this.category = category;
            this.reductionAmount = reductionAmount;
            this.newRemainingInCategory = newRemainingInCategory;
            this.goal = goal;
            this.newSavedAmount = newSavedAmount;
            this.newProgressPercent = newProgressPercent;
        }

        public Category getCategory() {
            return category;
        }

        public BigDecimal getReductionAmount() {
            return reductionAmount;
        }

        public BigDecimal getNewRemainingInCategory() {
            return newRemainingInCategory;
        }

        public SavingsGoal getGoal() {
            return goal;
        }

        public BigDecimal getNewSavedAmount() {
            return newSavedAmount;
        }

        public double getNewProgressPercent() {
            return newProgressPercent;
        }
    }
}

