    private final ObservableList<Category> categoryOptions = FXCollections.observableArrayList();
    private final ObservableList<SavingsGoal> goalOptions = FXCollections.observableArrayList();

    private final Label remainingResultLabel = new Label();
    private final Label savedResultLabel = new Label();
    private final Label progressResultLabel = new Label();

    public ReallocationView(CategoryRepository categoryRepository, SavingsGoalRepository savingsGoalRepository,
                             ReallocationService reallocationService,
                             ReadOnlyObjectProperty<YearMonth> selectedMonth) {
        this.categoryRepository = categoryRepository;
        this.savingsGoalRepository = savingsGoalRepository;
        this.reallocationService = reallocationService;
        this.selectedMonth = selectedMonth;
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Reallocation", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        categoryOptions.setAll(categoryRepository.findAll());
        goalOptions.setAll(savingsGoalRepository.findAll());
    }

    private VBox buildContent() {
        ComboBox<Category> categoryBox = new ComboBox<>(categoryOptions);
        categoryBox.setPromptText("Category to reduce");
        TextField amountField = new TextField();
        amountField.setPromptText("Reduction amount");
        ComboBox<SavingsGoal> goalBox = new ComboBox<>(goalOptions);
        goalBox.setPromptText("Savings goal");
        Label status = new Label();
        status.setWrapText(true);

        Button previewButton = new Button("Preview");
        previewButton.setOnAction(e -> {
            Category category = categoryBox.getValue();
            SavingsGoal goal = goalBox.getValue();
            if (category == null || goal == null) {
                status.setText("Category and savings goal are both required.");
                return;
            }
            try {
                BigDecimal amount = new BigDecimal(amountField.getText().trim());
                ReallocationService.ReallocationProjection projection = reallocationService.project(
                        category.getName(), amount, goal.getName(), selectedMonth.get());
                remainingResultLabel.setText("New remaining in " + projection.getCategory().getName() + ": $"
                        + projection.getNewRemainingInCategory());
                savedResultLabel.setText("New total saved for " + projection.getGoal().getName() + ": $"
                        + projection.getNewSavedAmount());
                progressResultLabel.setText("New progress: "
                        + String.format("%.0f%%", projection.getNewProgressPercent() * 100));
                status.setText("");
            } catch (NumberFormatException ex) {
                status.setText("Reduction amount must be a number.");
            } catch (IllegalArgumentException ex) {
                status.setText(ex.getMessage());
            }
        });

        for (Label label : List.of(remainingResultLabel, savedResultLabel, progressResultLabel)) {
            label.setWrapText(true);
        }

        FlowPane form = new FlowPane(8, 8, new Label("Reallocate:"), categoryBox, amountField, goalBox,
                previewButton, status);
        VBox results = new VBox(6, remainingResultLabel, savedResultLabel, progressResultLabel);

        VBox root = new VBox(16, form, results);
        root.setPadding(new Insets(12));
        return root;
    }
}

